let tjDataset=null,regionalCache=null;
let saved={};try{saved=JSON.parse(localStorage.getItem('lakewise-v1')||'{}');}catch{}
const state={weatherProvider:saved.weatherProvider==='openmeteo'?'openmeteo':'tjweather',shadowPreview:null,lang:saved.lang==='en'?'en':'zh',vision:['normal','accessible','mono'].includes(saved.vision)?saved.vision:'normal',reduced:saved.reduced??matchMedia('(prefers-reduced-motion: reduce)').matches,feedback:saved.feedback||{},water:saved.water||{},moods:saved.moods||{},thoughtEpoch:Date.now(),advice:{},aiChat:saved.aiChat||{},calib:saved.calib||{},bodyProfiles:saved.bodyProfiles||{},healthProfiles:saved.healthProfiles||{},measurements:saved.measurements||{},avatarId:avatarSpec(saved.avatarId).id,outfit:saved.outfit||'reference',mapMode:'world',mapMetric:'air',mapCoordinate:null,road:null,timer:!!saved.timer,selected:0,world:null,positions:[{id:'me',lon:DEST.bridge.c[0],lat:DEST.bridge.c[1],activity:'walk'}],telemetry:null,pending:false,stream:null,sse:false,streamKey:'',lastStream:0,lastReminder:Date.now(),routeRunning:false,routeReport:null};
const tr=(zh,en)=>state.lang==='zh'?zh:en;
const worldPanel=document.querySelector('.world');
const temperatureMap=createTemperatureMap($('temperatureCanvas'),{onRoad:road=>{state.road=road;renderRoad();},onInspect:(p,c)=>{state.mapCoordinate=c;renderTemperatureMap();}});
function setMapMode(mode){state.mapMode=mode==='temperature'?'temperature':'world';state.world?.stop();state.world?.setVisible?.(state.mapMode==='world');worldPanel.classList.toggle('is-temperature',state.mapMode==='temperature');worldPanel.classList.remove('controls-open');$('mapToolsToggle').setAttribute('aria-expanded','false');$('temperatureMap').hidden=state.mapMode!=='temperature';temperatureMap.setActive(state.mapMode==='temperature');document.querySelectorAll('[data-map-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mapMode===state.mapMode)));renderTemperatureMap();}
function renderTemperatureMap(){
 const scale=state.weatherProvider==='tjweather'?'local':'fixed';
 const points=temperatureMap.update(state.telemetry,{lang:state.lang,vision:state.vision,metric:state.mapMetric,person:person(),colorScale:scale});
 const domain=scale==='local'?temperatureDomain(points,state.mapMetric,{scopeBBox:state.world?.data.bbox||[120.108,30.215,120.176,30.281]}):[-10,40];
 const c=state.mapCoordinate||(person()?[person().lon,person().lat]:[120.142,30.248]),sample=temperatureMap.inspectAt(...c),value=sample?.[state.mapMetric];
 $('temperatureReading').closest('.temperature-reading').hidden=!state.mapCoordinate;
 $('temperatureReading').textContent=Number.isFinite(value)?value.toFixed(1)+'°C':'--';$('temperatureReadingTitle').textContent=state.mapCoordinate?tr('这里的附近预报','Nearby forecast here'):tr('西湖附近预报','West Lake forecast');$('temperatureCoordinate').textContent=c[1].toFixed(4)+'° N · '+c[0].toFixed(4)+'° E';
 const provider=state.weatherProvider==='tjweather'?'tjweather · '+tr('11/16下载预报','Nov 16 snapshot'):'Open-Meteo';
 const vals=points.filter(p=>p.lon>=120.108&&p.lon<=120.176&&p.lat>=30.215&&p.lat<=30.281).map(p=>p[state.mapMetric]).filter(Number.isFinite);
 const range=vals.length?Math.min(...vals).toFixed(1)+'–'+Math.max(...vals).toFixed(1)+'°C':'';
 $('temperatureSource').textContent=points.length?provider+' · '+tr((temperatureMap.getGrid()?.sourceCount||0)+'个源点 / 500米插值网格',(temperatureMap.getGrid()?.sourceCount||0)+' source points / 500 m interpolated grid')+' · '+range+' · '+tr('气象时刻 ','Weather time ')+hh(Math.min(...points.map(p=>p.time))*1000)+(scale==='local'?tr(' · 局地相对色阶',' · local relative scale'):''):tr('等待天气更新','Waiting for the forecast');
 const stops=Array.from({length:6},(_,i)=>domain[0]+(domain[1]-domain[0])*i/5);
 $('temperatureGradient').style.background='linear-gradient(90deg,'+stops.map(v=>temperatureColor(v,state.vision,domain)).join(',')+')';
 document.querySelectorAll('.temperature-ticks span').forEach((el,i)=>el.textContent=stops[i].toFixed(scale==='local'?1:0)+(i===5?'°C':''));
 document.querySelectorAll('[data-map-metric]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mapMetric===state.mapMetric)));
}

function persist(){try{localStorage.setItem('lakewise-v1',JSON.stringify({weatherProvider:state.weatherProvider,lang:state.lang,vision:state.vision,reduced:state.reduced,feedback:state.feedback,water:state.water,moods:state.moods,bodyProfiles:state.bodyProfiles,healthProfiles:state.healthProfiles,measurements:state.measurements,avatarId:state.avatarId,outfit:state.outfit,timer:state.timer,aiChat:state.aiChat,calib:state.calib}));}catch{}}
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,5500);}
function hh(ts){return new Intl.DateTimeFormat(state.lang==='zh'?'zh-CN':'en-GB',{hour:'2-digit',minute:'2-digit',hour12:false,timeZone:'Asia/Shanghai'}).format(new Date(ts));}
function applyLanguage(){document.documentElement.lang=state.lang==='zh'?'zh-CN':'en';document.title=tr('FeelsLike · 西湖气候沙盘','FeelsLike · Westlake Climate Fieldlab');const MAPKEYS=new Set(['modeWorld','modeTemperature','mapTools','follow','eye','overview']);document.querySelectorAll('[data-i]').forEach(el=>{const t=TEXT[el.dataset.i];if(!t)return;const zh=t[0],en=t[1];const single=MAPKEYS.has(el.dataset.i)||zh===en||zh.length>24;el.textContent=single?(state.lang==='zh'?zh:en):zh+' / '+en;});document.querySelectorAll('[data-placeholder-i]').forEach(el=>el.placeholder=TEXT[el.dataset.placeholderI][state.lang==='zh'?0:1]);$('language').value=state.lang;state.world?.setLang(state.lang);const destination=$('destination').value;$('destination').innerHTML=['landmark','pier'].map(kind=>`<optgroup label="${TEXT[kind==='pier'?'groupPiers':'groupLandmarks'][state.lang==='zh'?0:1]}">${Object.entries(DEST).filter(([,p])=>(p.kind||'landmark')===kind).map(([key,p])=>`<option value="${key}">${p[state.lang]}</option>`).join('')}</optgroup>`).join('');$('destination').value=destination||'bridge';renderPeople();render();renderSources();}
let portraitCache={};
function avatarFace(a){return `<span class="avatar-face" style="--hair:${a.hairColor};--eyes:${a.eyes};--shirt:${a.shirt}"><i></i><i></i></span>`;}
function renderPeople(){const a=avatarSpec(state.avatarId);$('people').innerHTML=`<button id="avatarOpen" class="avatar-open"><span class="avatar-mini">${portraitCache[a.id]?`<img src="${portraitCache[a.id]}" alt="">`:avatarFace(a)}</span><span><b>${a[state.lang]}</b><small>${tr('换个样子逛西湖','A new look for your walk')}</small></span><span class="avatar-change">${tr('选择人物 ↗','Choose a character ↗')}</span></button>`;}
function openAvatarDialog(){state.world?.stop();$('avatarChoices').innerHTML=AVATARS.map(a=>`<button data-avatar="${a.id}" aria-pressed="${a.id===state.avatarId}"><span class="avatar-portrait">${portraitCache[a.id]?`<img src="${portraitCache[a.id]}" alt="">`:avatarFace(a)}</span><b>${a[state.lang]}</b></button>`).join('');$('avatarDialog').showModal();void renderAvatarHeads(AVATARS.map(a=>a.id),(id,url)=>{portraitCache[id]=url;const host=$('avatarChoices').querySelector(`[data-avatar="${id}"] .avatar-portrait`);if(host){const img=document.createElement('img');img.src=url;img.alt='';host.replaceChildren(img);}renderPeople();});}
async function chooseAvatar(id){const buttons=[...$('avatarChoices').querySelectorAll('button')];buttons.forEach(b=>{b.disabled=true;});$('avatarChoices').setAttribute('aria-busy','true');try{const next=avatarSpec(id).id;const changed=await state.world?.setAppearance(next,'reference');if(changed===false)return;state.avatarId=next;state.outfit='reference';persist();renderPeople();render();$('avatarDialog').close();}catch{toast(tr('人物还没加载好，点一下再试试吧。','The character did not finish loading. Tap to try again.'));}finally{buttons.forEach(b=>{b.disabled=false;});$('avatarChoices').setAttribute('aria-busy','false');}}

function person(){return state.positions[0];}
function dataForPerson(){const p=person();if(!p)return undefined;const report=currentPersonReport(state.telemetry?.people?.find(d=>d.id===p.id),p,state.feedback[p.id]);const base=personComfort(report,p,state.feedback[p.id],state.measurements[p.id]);const shade=state.world?.shadeContext?.();const local=localThermalEstimate(base.adviceWeather,shade,{preview:state.shadowPreview!=null});base.geometryThermal=local;base.shadeContext=shade;
 if(local&&!state.shadowPreview){base.adviceWeather=local.weather;const reasons=new Set([...base.environmentalReminder.reasons,...environmentReminder(local.weather,p.activity).reasons].filter(r=>r!=='missing'));const ordered=['heat','wind','cold','activity','rain','uv'].filter(r=>reasons.has(r));const env={code:ordered[0]||base.environmentalReminder.code,level:ordered.some(r=>r==='heat'||r==='activity')?'attention':ordered.length?'notice':base.environmentalReminder.level,reasons:[...reasons]};base.environmentalReminder=env;Object.assign(base,applyComfortFeedback(env,state.feedback[p.id],p.activity));if(!['heat','cold'].includes(temperatureSignal(base.warningWeather)))base.warningWeather=local.weather;}
 return base;}

function placeFor(p){if(!p)return {zh:'断桥',en:'Broken Bridge'};let near=Object.values(DEST).reduce((a,b)=>Math.hypot((p.lon-b.c[0])*96400,(p.lat-b.c[1])*111320)<Math.hypot((p.lon-a.c[0])*96400,(p.lat-a.c[1])*111320)?b:a);return near;}
function metric(id,value,unit='',decimals=0){$(id).replaceChildren();$(id).append(document.createTextNode(Number.isFinite(value)?value.toFixed(decimals):'--'));if(unit){const small=document.createElement('small');small.textContent=unit;$(id).append(small);}}
function weatherName(code){if(code==null)return '--';if(code===0)return tr('晴','Clear');if(code<=3)return tr('多云','Cloudy');if(code<=48)return tr('雾','Fog');if(code<=67)return tr('雨','Rain');if(code<=77)return tr('雪','Snow');if(code<95)return tr('阵雨','Showers');return tr('雷暴','Thunderstorm');}
function render(){const p=person(),d=dataForPerson(),w=d?.weather;renderPointThermal(d);const place=placeFor(p);$('personPlace').textContent=place[state.lang];$('placeLabel').textContent=place[state.lang]+' · '+tr('沿 OSM 路网','ON OSM ROADS');if(p){$('personCoord').textContent=p.lat.toFixed(5)+'° N / '+p.lon.toFixed(5)+'° E';$('activity').value=p.activity;}
 metric('feelsValue',d?.geometryThermal?.value??w?.apparent_temperature,'',1);metric('airValue',w?.temperature_2m,'°C',1);metric('humidityValue',w?.relative_humidity_2m,'%');metric('windValue',w?.wind_speed_10m,'m/s',1);metric('solarValue',w?.shortwave_radiation,'W/m²');$('uvValue').textContent=Number.isFinite(w?.uv_index)?w.uv_index.toFixed(1):'--';$('rainValue').textContent=Number.isFinite(w?.precipitation_probability)?w.precipitation_probability+'%':'--';$('gustValue').textContent=Number.isFinite(w?.wind_gusts_10m)?w.wind_gusts_10m.toFixed(1)+' m/s':'--';$('condition').textContent=weatherName(w?.weather_code);
 document.querySelector('[data-i="feelsLike"]').textContent=d?.geometryThermal?tr('当前位置体感（UTCI估算）','Local thermal estimate (UTCI)'):state.weatherProvider==='tjweather'?tr('区域参考体感（估算）','Regional apparent estimate'):TEXT.feelsLike[state.lang==='zh'?0:1];
 const point=state.telemetry?.points?.find(x=>x.id===d?.pointId);
 const grids=new Set((state.telemetry?.points||[]).map(p=>p.weather?.latitude+','+p.weather?.longitude));if(grids.size===1)$('gridNote').textContent=tr('西湖周边天气 · Open-Meteo','West Lake forecast · Open-Meteo');
 $('weatherSource').textContent=w?`${state.weatherProvider==='tjweather'?'tjweather · '+tr('下载预报','downloaded forecast'):'Open-Meteo'} · ${point?.[state.lang==='zh'?'name':'en']||''} · ${tr('气象时刻','Weather time')} ${hh(w.time*1000)}${w.stale?tr(' · 已过期',' · stale'):''}`:tr('天气暂时没更新，稍等一下。','Waiting for the latest weather.');
 $('connection').textContent=w&&!w.stale?(state.weatherProvider==='tjweather'?tr('下载预报','Saved forecast'):tr('气象已连接','Weather live')):w?tr('气象已过期','Weather stale'):state.pending?tr('正在连接天气','Connecting weather'):tr('气象未连接','No weather');
 if(state.weatherProvider==='tjweather'){$('gridNote').textContent=tr('tjweather 预报快照 · '+(state.telemetry?.points?.length||81)+' 个请求点','tjweather forecast snapshot · requested points');$('weatherSource').textContent+=tr(' · 体感估算',' · apparent estimate');}
 if(d?.geometryThermal&&Number.isFinite(w?.apparent_temperature))$('weatherSource').textContent+=tr(' · 区域参考体感 ',' · Regional reference ')+w.apparent_temperature.toFixed(1)+'°C';
 $('tickTime').textContent=state.telemetry?hh(state.telemetry.computedAt):'--';
 const feedback=state.feedback[p?.id];document.querySelectorAll('[data-feel]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.feel===feedback?.feel)));$('feedbackCount').textContent=feedback?hh(feedback.at):TEXT.optional[state.lang==='zh'?0:1];const off=personalOffset(p?.id),cn=$('calibNote');if(cn)cn.textContent=off!=null?tr('你的冷热校准 '+off.toFixed(1)+'°C（自报累积，非医学阈值）','Your calibration '+off.toFixed(1)+'°C (self-report, not a medical threshold)'):tr('冷热校准：再记几次感受后生效','Calibration activates after a few check-ins');
 const water=state.water[p?.id];$('lastWater').textContent=water?tr('上次记录补水：','Last water logged: ')+hh(water):TEXT.timerHint[state.lang==='zh'?0:1];
 state.world?.setWeather?.(w);renderAction(d);renderPersonalization(d);renderMood(d?.warningWeather||w);renderOverhead(d);renderHealth(d?.warningWeather||w);renderObservation(d?.observation);renderOutfit(d);renderRoad();renderMetabolism();renderForecast(w);renderRouteStatus();renderTemperatureMap();
}

function renderMood(w){const mood=state.moods[bodyId()]?.value;document.querySelectorAll('[data-mood]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mood===mood)));const signal=temperatureSignal(w);$('moodTip').textContent=signal==='unknown'?tr('这会儿心情怎么样？','How are you feeling right now?'):signal==='heat'?tr('天热容易心烦，去树荫下歇歇，给自己一点清凉。','Feeling tired or irritable in the heat? Take a little break in the shade.'):signal==='cold'?tr('天有点冷，穿暖和些，找个避风的地方歇歇。','It is chilly. Wrap up and find a sheltered spot to relax.'):tr('想吃鱼、跳支舞，还是坐着看看湖？今天听你的。','Fish, a little dance, or a moment by the lake? It is your day.');const expressions={};for(const p of state.positions){const weather=w;expressions[p.id]=avatarExpression({weather,mood:state.moods[p.id]?.value,id:p.id,now:state.reduced?state.thoughtEpoch:Date.now()});}state.world?.setExpressions?.(expressions);}

function renderOverhead(d){const id=bodyId();state.world?.setOverhead?.({[id]:{thermal:overheadThermal(d,{preview:state.shadowPreview!=null}),advice:state.advice[id]}});}

function fillHealthForm(){const p=normalizeHealth(state.healthProfiles[bodyId()]);document.querySelectorAll('[data-health]').forEach(e=>e.checked=p.conditions.includes(e.dataset.health));$('fluidRestricted').checked=p.fluidRestricted;$('healthOther').value=p.otherText;syncHealthDraft();}
function syncHealthDraft(){const other=document.querySelector('[data-health="other"]').checked;$('healthOtherField').hidden=!other;$('healthOther').disabled=!other;$('healthOther').required=other;}
$('healthForm').addEventListener('change',e=>{const healthy=document.querySelector('[data-health="healthy"]');if(e.target===healthy&&healthy.checked){document.querySelectorAll('[data-health]').forEach(input=>{if(input!==healthy)input.checked=false;});$('fluidRestricted').checked=false;$('healthOther').value='';}else if(e.target.checked&&(e.target.matches('[data-health]')||e.target.id==='fluidRestricted'))healthy.checked=false;syncHealthDraft();});
function renderHealth(w){const p=healthSupport(state.healthProfiles[bodyId()],w),lang=state.lang==='zh'?0:1;$('healthResult').textContent=p.recorded?tr('已记下：','Saved: ')+[...p.conditions.map(k=>HEALTH_OPTIONS[k][lang]+(k==='other'&&p.otherText?'：'+p.otherText:'')),...(p.fluidRestricted?[tr('按医嘱饮水','Clinician-directed drinking plan')]:[])].join('、')+'。'+p[state.lang]:tr('可以告诉我需要特别照顾的身体情况。','Tell us about anything that needs a little extra care.');
 $('waterButton').textContent=p.fluidRestricted?tr('✓ 已按计划饮水','✓ Followed my drinking plan'):TEXT.waterDone[lang];const plan=reminderPlan(state.healthProfiles[bodyId()],w,state.feedback[bodyId()],person()?.activity);$('reminderLabel').textContent=tr('每隔 '+plan.minutes+' 分钟提醒我'+(plan.mode==='rest'?'休息':'喝水'),'Remind me to '+(plan.mode==='rest'?'rest':'drink water')+' every '+plan.minutes+' minutes');
 if(!p.active)return;
 const code=dataForPerson()?.reminder?.code||'unknown';
 if(p.cold&&['routine','unknown','activity'].includes(code)){$('actionTitle').textContent=tr('先好好休息，等舒服些再出门','Rest first and head out when you feel better');$('actionBody').textContent=p[state.lang];return;}
 if(p.fluidRestricted){if(['routine','unknown','heat','activity','personalHot'].includes(code)){$('actionTitle').textContent=p.hot||code==='personalHot'?tr('先到阴凉处歇歇吧','Take a shady break'):tr('按自己的节奏，注意休息哦','Take your time and plan little breaks');$('actionBody').textContent=p[state.lang];}else $('actionBody').textContent+=' '+p[state.lang];}
 else $('actionBody').textContent+=' '+p[state.lang];
}
function renderObservation(context){const c=context||{active:false,status:'empty'};$('localReading').hidden=!c.active;$('measurementClear').hidden=!state.measurements[bodyId()];const labels={empty:tr('记一下这里的气温，看看体感会怎样变化。','Record the air temperature here to see how it changes the estimate.'),expired:tr('这次测温已有一阵子，再测一次吧。','Time for a fresh temperature reading.'),moved:tr('已经走远了，记一下新位置的气温吧。','You have moved on. Record the temperature at this spot.'),invalid:tr('检查一下测温记录，再保存一次吧。','Check your measurement and save it again.')};
 if(c.active){$('localAir').textContent=c.air.toFixed(1)+'°C';$('localFeels').textContent=Number.isFinite(c.apparent)?c.apparent.toFixed(1)+'°C':'--';$('localSource').textContent=c.borrowedHumidity||c.borrowedWind?tr('气温来自你的记录，湿度或风参考附近天气。','Your air reading, with nearby weather for humidity or wind.'):tr('按你的测温、湿度和风速记录估算。','Estimated from your air temperature, humidity and wind readings.');$('measurementStatus').textContent=tr('已记录 · '+c.ageMinutes+' 分钟前','Recorded '+c.ageMinutes+' minutes ago')+(Number.isFinite(c.apparent)?'':tr(' · 补充湿度和风速后可估算体感。',' · Add humidity and wind to estimate how it feels.'));}
 else $('measurementStatus').textContent=labels[c.status]||labels.empty;
}
function renderOutfit(d){const r=recommendOutfit(d?.adviceWeather,state.feedback[bodyId()],person()?.activity,state.healthProfiles[bodyId()]);$('outfitText').textContent=r[state.lang];$('outfitItems').replaceChildren();for(const item of r.items){const li=document.createElement('li');li.textContent=item[state.lang];$('outfitItems').append(li);}$('outfitApply').disabled=!r.available;$('outfitBasis').textContent=r.available?r.temperature.toFixed(1)+'°C · '+(d?.observation?.active?Number.isFinite(d.observation.apparent)?tr('现场参考体感','Local apparent estimate'):tr('现场气温','Local air temperature'):tr(state.weatherProvider==='tjweather'?'区域参考体感':'预报体感',state.weatherProvider==='tjweather'?'Regional estimate':'Forecast apparent temperature')):tr('等待天气更新','Awaiting the forecast');$('outfitReset').hidden=state.outfit==='reference';}
function renderRoad(){const road=state.road;$('roadInfo').hidden=!road;if(!road)return;const label=roadLabel(road,state.lang);$('roadName').textContent=label.name;$('roadType').textContent=label.type;}
function bodyId(){return person()?.id||'me';}
function fillBodyForm(){const p=state.bodyProfiles[bodyId()]||{};for(const [id,key]of [['heightCm','heightCm'],['weightKg','weightKg'],['bodyAge','age']])$(id).value=p[key]??'';$('bodySex').value=p.sex||'unspecified';}
function renderMetabolism(){const p=state.bodyProfiles[bodyId()],r=estimateMetabolism(p);if(!p){$('metabolismResult').textContent=tr('愿意的话，填一点你的资料吧。','Add a few details whenever you like.');return;}if(r.status==='outside_reference_age'){$('metabolismResult').textContent=tr('资料已保存，目前支持计算 19–78 岁的身体消耗。','Details saved. Energy estimates are available for ages 19–78.');return;}if(r.status!=='ok'){$('metabolismResult').textContent=tr('请检查输入信息。','Please check the profile inputs.');return;}const number=a=>r.range?a.map(x=>Math.round(x)).join('–'):Math.round(a[0]);$('metabolismResult').textContent=tr('静息能量估算：','Estimated resting energy: ')+number(r.kcalPerDay)+' kcal/'+tr('天','day')+'\n'+tr('休息时身体产热约 ','Equivalent resting power ≈ ')+number(r.watts)+' W\n'+(r.range?tr('根据目前填写的资料，消耗大约在这个范围。','Your estimate falls within this range with the details provided.'):'Mifflin–St Jeor · '+tr('每日静息消耗','daily resting energy'));}
async function checkApi(){if(state.weatherProvider==='tjweather'){await poll();$('apiStatus').textContent=tr('当前使用 11/16 下载预报快照。','Using the forecast snapshot downloaded on Nov 16.');return;}const el=$('apiStatus');el.textContent=tr('正在看看天气有没有更新…','Checking for fresh weather…');try{await weatherClient.load({force:true});await poll();}catch{}const d=weatherClient.diagnostics();if(d.status==='ok'||d.status==='stale'){el.textContent=tr('天气来源：Open-Meteo','Weather source: Open-Meteo')+'\n'+tr('获取方式：设备直连','Connection: direct from this device')+'\n'+(d.status==='ok'?tr('连接状态：已连接','Status: connected'):tr('连接状态：等待新天气','Status: awaiting fresh weather'))+'\n'+tr('最近获取：','Last fetched: ')+(d.lastSuccessAt?hh(d.lastSuccessAt):'--');return;}try{const r=await fetch('/api/diagnostics',{signal:AbortSignal.timeout(25000)});if(!r.ok)throw Error();const server=await r.json();el.textContent=tr('设备和网页服务正在尝试更新天气。','The device and service are trying to update the forecast.')+'\n'+(server.weather.lastHttpStatus===429||d.errorCode==='rate_limited'?tr('天气服务请求较多，稍后自动重试。','The weather service is busy. We will try again later.'):tr('检查网络后再刷新看看吧。','Check your connection and try refreshing.'));}catch{el.textContent=tr('这会儿连不上天气服务，稍后再试试吧。','Could not reach the weather service. Try again in a moment.');}}
function renderPersonalization(d){
 const p=d?.personalization;
 const local=state.feedback[person()?.id];$('clearFeedback').hidden=!local;
 if(!p?.active||!local){const fresh=local&&Date.now()-local.at<2*3600000&&(!local.activity||local.activity===person()?.activity);$('personalization').textContent=fresh?tr('收到啦，正在更新你的提醒…','Got it. Updating your reminder…'):local?tr('现在感觉有变化吗？再点一次，更新一下吧。','Feeling different now? Tap again to update.'):tr('冷了、热了，都可以告诉我。','Tell us whenever you feel warm or cool.');return;}
 const feel={hot:tr('偏热','warm'),cold:tr('偏冷','cool'),fine:tr('刚好','comfortable')}[p.feel];
 $('personalization').textContent=tr(`${p.ageMinutes} 分钟前，你觉得“${feel}”。现在呢？`,`You felt ${feel} ${p.ageMinutes} minutes ago. How about now?`);
 if(d.reminder.code==='personalHot'){$('actionTitle').textContent=tr('觉得热了？先歇一会儿','You feel warm. Take a break.');$('actionBody').textContent=tr('放慢脚步，去阴凉处坐坐，喝口水再出发。','Slow down, find some shade and have a drink before heading on.');$('actionBadge').textContent=tr('你的体感','Your feedback');}
 if(d.reminder.code==='personalCold'){$('actionTitle').textContent=tr('有点冷？加件衣服吧','You feel cool. Add a layer.');$('actionBody').textContent=tr('披上外套，找个避风的地方，暖和了再慢慢逛。','Add a layer and find a sheltered spot to warm up before walking on.');$('actionBadge').textContent=tr('你的体感','Your feedback');}
 if(p.feel==='hot'&&!['heat','personalHot'].includes(d.reminder.code))$('actionBody').textContent+=' '+tr('你刚才觉得热，也可以先在阴凉处休息。','You felt warm; take a shady break as well.');
}
function payloadPeople(){return telemetryPeople(state.positions,state.feedback);}
function jump(key){state.world?.jumpTo?.(key);state.positions=state.world?.state()||[];state.routeRunning=false;document.querySelectorAll('button[data-camera]').forEach(b=>b.classList.toggle('selected',b.dataset.camera==='follow'));$('destination').value=key;worldPanel.classList.remove('controls-open');$('mapToolsToggle').setAttribute('aria-expanded','false');render();syncStream();void poll();toast(tr('已跳转至 ','Jumped to ')+(DEST[key]?.[state.lang]||''));}
function renderRouteStatus(){const r=state.routeReport;if(!r)return;$('walkRoute').textContent=state.routeRunning?tr('暂停漫步 ■','Pause walk ■'):TEXT.walkRoute[state.lang==='zh'?0:1];$('routeStatus').textContent=r.stopped?tr('已停下','Stopped'):r.arrived?tr('已抵达','Arrived'):r.ok?((DEST[r.destinationKey]?.[state.lang]||'')+(r.meters?' · '+Math.round(r.meters)+' m':'')):tr('这段路走不过去，试试直接前往吧。','No walking route here. Try Go here.');}
function renderAction(d){const code=d?.reminder?.code||'unknown';const messages={
 unknown:[['记得带水，注意休息哦','Bring water and take little breaks'],['天气还在更新，出发前再看一眼。先把水装好，沿途慢慢逛。','The weather is updating. Check again before you head out, pack some water and take your time.']],
 heat:[['有点热，去阴凉处歇歇吧','It is hot. Find a shady spot'],['走慢一点，找片树荫坐坐，记得喝水。','Slow down, sit in the shade and remember to drink water.']],
 activity:[['跑得热了？放慢一点吧','Getting warm? Slow down a little'],['这会儿天气偏暖，放慢节奏，喝口水再继续。','It is warm out. Ease your pace and have some water before continuing.']],
 uv:[['阳光有点强，记得遮阳哦','A sunny day calls for some shade'],['帽子、遮阳伞和防晒用品带好，沿着有树荫的地方走吧。','Bring a hat, sun protection or a parasol, and choose a shaded path.']],
 rain:[['带把伞，湖边慢慢走','Bring an umbrella and take it slowly'],['可能会下雨，出发前带好雨具，石阶和湖边留意脚下。','Rain is possible. Bring rain cover and watch your footing by the lake and on steps.']],
 wind:[['湖边风大，留意身边哦','It is windy by the lake'],['拿好帽子和随身物品，先到避风处歇歇。','Hold on to your hat and belongings, and take a break somewhere sheltered.']],
 cold:[['天有点冷，加件衣服吧','A little chilly? Add a layer'],['穿暖和些，休息时找个避风的地方。','Wrap up warmly and find a sheltered spot for your breaks.']],
 routine:[['记得带水，注意休息哦','Bring water and take little breaks'],['走累了就坐坐，喝口水，再看看湖边的风景。','Sit down when you need a rest, have some water and enjoy the lakeside view.']]
 };const m=messages[code]||messages.unknown,i=state.lang==='zh'?0:1;$('actionTitle').textContent=m[0][i];$('actionBody').textContent=m[1][i];const notes={heat:['天气偏热','Hot weather'],cold:['天气偏冷','Chilly weather'],activity:['活动时放慢节奏','Ease your pace'],wind:['阵风较强','Strong gusts'],rain:['留意降雨','Watch for rain'],uv:['记得遮阳','Sun protection']},extra=(d?.reminder?.reasons||[]).filter(k=>k!==code&&notes[k]);$('weatherAlerts').textContent=extra.length?tr('同时留意：','Also: ')+extra.map(k=>notes[k][i]).join(' · '):'';$('weatherAlerts').hidden=!extra.length;$('actionBadge').textContent=code==='unknown'?tr('出发前','Before you go'):code==='routine'?tr('慢慢逛','Take your time'):tr('小提醒','A reminder');}
function renderForecast(w){const h=w?.hourly;if(!h?.time?.length){$('forecastChart').textContent=tr('正在整理接下来 24 小时的天气…','Preparing your hourly forecast…');$('forecastTip').textContent=TEXT.forecastUnavailable[state.lang==='zh'?0:1];return;}const rows=forecastRows(w);if(rows.length<2){$('forecastChart').textContent=tr('接下来的天气还在更新，稍后再看看。','The next forecast is updating. Check back shortly.');$('forecastTip').textContent=TEXT.forecastUnavailable[state.lang==='zh'?0:1];return;}const W=Math.max(300,Math.min(720,$('forecastChart').clientWidth||720)),H=92,pad=15,lo=Math.min(...rows.map(p=>p.temp))-2,hi=Math.max(...rows.map(p=>p.temp))+2;const x=i=>pad+i/(rows.length-1)*(W-pad*2),y=v=>H-18-(v-lo)/(hi-lo)*(H-32);const path=rows.map((p,i)=>(i?'L':'M')+x(i).toFixed(1)+' '+y(p.temp).toFixed(1)).join(' ');let labels='';for(let i=0;i<rows.length;i+=4)labels+=`<text x="${x(i)}" y="${H+6}" text-anchor="middle">${hh(rows[i].time*1000)}</text><text x="${x(i)}" y="${y(rows[i].temp)-10}" text-anchor="middle">${Math.round(rows[i].temp)}°</text>`;$('forecastChart').innerHTML=`<svg viewBox="0 0 ${W} 105" role="img" aria-label="${tr('逐时预报体感','Hourly apparent temperature')}"><defs><linearGradient id="chartFill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="var(--green)" stop-opacity=".16"/><stop offset="1" stop-color="var(--green)" stop-opacity="0"/></linearGradient></defs><path class="area" d="${path} L${x(rows.length-1)} ${H-10} L${pad} ${H-10} Z"/><path class="curve" d="${path}"/>${labels}</svg>`;const peak=rows.reduce((a,b)=>a.temp>b.temp?a:b);$('forecastTip').textContent=(rows.length<24?tr('已更新 '+rows.length+' 小时 · ','Updated '+rows.length+' hours · '):'')+tr('最高预报体感 ','Forecast peak ')+peak.temp.toFixed(1)+'°C · '+hh(peak.time*1000)+(w.stale?tr(' · 数据已过期',' · stale data'):'');}
function renderSources(learn=false){const t=tr;$('sourceContent').innerHTML=`${learn?`<h3>${t('为什么同一天，体感会不同？','Why can the same day feel different?')}</h3><p>${t('湿度高，汗就没那么容易蒸发；风吹过来，会带走身体的热量；晒着太阳、加快脚步，也会让人觉得更热。走累了，找片树荫歇歇，听听身体的感受。','Humidity slows sweat evaporation, a breeze carries heat away, and sunshine or a brisk pace can make you feel warmer. Take a shady break and notice how you feel.')}</p>`:''}
 <h3>${t('沿着西湖逛逛','Explore West Lake')}</h3><p>${t('道路、湖岸、建筑位置和码头来自 OpenStreetMap。地形使用 Copernicus GLO-30 数据，高低起伏放大了 1.6 倍，方便看清湖边的山势。雷峰塔按照八角五层的外形绘制。','Roads, shorelines, buildings and piers come from OpenStreetMap. Copernicus GLO-30 supplies the terrain, with heights enlarged 1.6 times to show the hills. Leifeng Pagoda is drawn with eight sides and five storeys.')}</p>
 <p><a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">© OpenStreetMap contributors · ODbL</a><br><a href="https://registry.opendata.aws/copernicus-dem/" target="_blank" rel="noopener">Copernicus GLO-30</a><br>© DLR e.V. 2010–2014 · © Airbus Defence and Space GmbH 2014–2018 · EU / ESA</p>
 <h3>${t('天气从哪里来？','Where does the weather come from?')}</h3><p>${t('Open-Meteo 提供西湖周边的天气预报，由这台设备直接获取，缓存 10 分钟。人物走到哪里，就显示附近的天气。天气时间会写在温度下方，连接状态也可以展开查看。','This device fetches Open-Meteo forecasts around West Lake directly and caches them for 10 minutes. Your character shows the nearby weather as you walk. The forecast time appears below the temperature; open Weather connection for more details.')}</p><p><a href="https://open-meteo.com/en/docs" target="_blank" rel="noopener">Open-Meteo</a></p>
 <h3>${t('给你的提醒','Your little reminders')}</h3><p>${t('天热时，提醒你补水、找阴凉；天冷时，记得加衣。阳光强、下雨或风大时，也会给你一句提醒。点一下自己的冷热感受，提醒会跟着调整。','On hot days, pause for water and shade. On chilly days, bring an extra layer. Strong sunshine, rain and gusts bring their own reminders. Tap how warm or cool you feel to adjust your advice.')}</p><p><a href="https://www.cdc.gov/heat-health/risk-factors/heat-and-outdoor-workers.html" target="_blank" rel="noopener">CDC · ${t('热天的户外活动','Outdoor activity in hot weather')}</a><br><a href="https://www.osha.gov/heat-exposure/water-rest-shade" target="_blank" rel="noopener">OSHA · ${t('喝水、休息、找阴凉','Water, rest and shade')}</a></p>
 <h3>${t('把现场的感觉也记下来','Add what you notice here')}</h3><p>${t('可以记录温度计气温，再选一下偏冷、刚好或偏热。测温会更新现场参考体感和穿搭；湿度与风速没填时，先参考附近天气。走出约100米或过了30分钟，再测一次吧。你说的冷热感受会用来调整建议。','Record a thermometer reading and choose cool, comfortable or warm. The reading updates your local estimate and outfit advice; nearby weather supplies humidity and wind when left blank. Take another reading after about 100 metres or 30 minutes. Your comfort check-in helps tailor the advice.')}</p>
 <h3>${t('让提醒更合你心意','Make reminders work for you')}</h3><p>${t('保存健康情况后，休息和饮水提醒会跟着调整。需要额外照顾、又觉得热时，开启提醒后每15分钟问候一次；其余情况每30分钟。医生叮嘱限制饮水时，就按医生给你的安排来。','Saved health details adjust your rest and water reminders. If you need extra care and feel hot, enabled check-ins come every 15 minutes; otherwise every 30 minutes. Follow your clinician’s drinking plan if you have a fluid restriction.')}</p>
 <h3>${t('身体每天消耗多少？','How much energy does your body use?')}</h3><p>${t('填写身高、体重、年龄和性别后，可以用 Mifflin–St Jeor 公式估算每天的静息能量消耗。目前支持 19–78 岁，性别留空时会显示一个范围。','Height, weight, age and sex are used in the Mifflin–St Jeor formula to estimate daily resting energy use. Estimates are available for ages 19–78; leaving sex blank gives a range.')}</p><p><a href="https://pubmed.ncbi.nlm.nih.gov/2305711/" target="_blank" rel="noopener">Mifflin–St Jeor · 1990</a></p>
 <h3>${t('想去坐船？','Fancy a boat ride?')}</h3><p>${t('在地点菜单里选择“游船码头”，就能跳转到湖边的码头。','Choose Boat piers in the destination menu to visit a lakeside pier.')}</p><p><a href="https://hznews.hangzhou.com.cn/chengshi/content/2024-04/06/content_8711483.htm" target="_blank" rel="noopener">${t('看看西湖游船介绍 ↗','Read the West Lake boat guide ↗')}</a></p>
 <h3>${t('你的记录','Your check-ins')}</h3><p>${t('身体资料、心情和补水记录保存在这台设备。服务会结合人物位置、活动和近期体感更新提醒。补水提醒在页面打开时生效。','Body details, moods and water logs stay on this device. The service uses your character’s location, activity and recent comfort check-in to update reminders. Water reminders work while this page is open.')}</p>`;}
function acceptTelemetry(data){state.telemetry=data;render();}
async function poll(){if(state.pending||!state.positions.length)return;state.pending=true;render();try{
 if(state.weatherProvider==='tjweather'){tjDataset=await loadTjWeather();const report=tjWeatherReport(tjDataset,state.positions);const regional=regionalCache?browserWeatherReport(regionalCache,state.positions,state.feedback):null;for(const target of [...report.points,...report.people]){const w=target.weather;if(!w)continue;const extra=regional?.people?.[0]?.weather;if(extra&&!extra.stale){w.shortwave_radiation=extra.shortwave_radiation;w.radiationSource='Open-Meteo regional';}w.apparent_temperature=apparentEstimate(w.temperature_2m,w.relative_humidity_2m,w.wind_speed_10m,w.shortwave_radiation);w.apparentEstimated=true;const hourly=w.hourly;if(hourly)w.hourly={...hourly,apparent_temperature:hourly.time.map((t,i)=>apparentEstimate(hourly.temperature_2m[i],hourly.relative_humidity_2m[i],hourly.wind_speed_10m[i],null))};}acceptTelemetry(report);return;}
 const cache=await weatherClient.load();regionalCache=cache;state.stream?.close();state.stream=null;state.sse=false;acceptTelemetry(browserWeatherReport(cache,state.positions,state.feedback));
 }catch{try{const r=await fetch('/api/telemetry',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({people:payloadPeople()}),signal:AbortSignal.timeout(25000)});if(!r.ok)throw Error('backend');acceptTelemetry(await r.json());}catch{if(state.telemetry)for(const p of [...state.telemetry.people,...state.telemetry.points])if(p.weather)p.weather.stale=true;render();}}finally{state.pending=false;}}
function syncStream(){if(!state.sse||!state.positions.length)return;const key=JSON.stringify(payloadPeople().map(p=>({...p,lon:+p.lon.toFixed(4),lat:+p.lat.toFixed(4)})));if(key===state.streamKey&&state.stream)return;if(Date.now()-state.lastStream<5000)return;state.streamKey=key;state.lastStream=Date.now();state.stream?.close();state.stream=new EventSource('/api/events?people='+encodeURIComponent(key));state.stream.onmessage=e=>{try{acceptTelemetry(JSON.parse(e.data));}catch{}};state.stream.onerror=()=>{state.stream?.close();state.stream=null;state.sse=false;void poll();};}
document.addEventListener('click',e=>{
 const btn=e.target.closest('button');if(!btn)return;
 if(btn.dataset.mood){state.moods[bodyId()]={value:btn.dataset.mood,at:Date.now()};persist();render();return;}
 if(btn.dataset.landmark){jump(btn.dataset.landmark);return;}
 if(btn.dataset.mapMode){setMapMode(btn.dataset.mapMode);return;}
 if(btn.dataset.mapMetric){state.mapMetric=btn.dataset.mapMetric;renderTemperatureMap();return;}
 if(btn.id==='avatarOpen'){openAvatarDialog();return;}
 if(btn.dataset.avatar){chooseAvatar(btn.dataset.avatar);return;}
 if(btn.dataset.camera){state.world?.setCamera(btn.dataset.camera);document.querySelectorAll('button[data-camera]').forEach(b=>b.classList.toggle('selected',b===btn));}
 if(btn.dataset.layer){state.world?.setLayer(btn.dataset.layer);document.querySelectorAll('[data-layer]').forEach(b=>b.classList.toggle('selected',b===btn));}
 if(btn.dataset.step)state.world?.step(btn.dataset.step);
 if(btn.dataset.feel&&person()){state.feedback[person().id]={feel:btn.dataset.feel,at:Date.now(),activity:person().activity};const cal=state.calib[person().id]||(state.calib[person().id]={hot:0,cold:0,fine:0});cal[btn.dataset.feel]=(cal[btn.dataset.feel]||0)+1;persist();render();state.lastStream=0;syncStream();void poll();toast(tr('收到啦，按你的感受调整提醒。','Got it. Tailoring your reminder.'));}
});
$('measurementForm').onsubmit=e=>{e.preventDefault();if(!person())return;const observation={temperature:Number($('measuredAir').value),humidity:$('measuredHumidity').value===''?null:Number($('measuredHumidity').value),wind:$('measuredWind').value===''?null:Number($('measuredWind').value),at:Date.now(),lon:person().lon,lat:person().lat};const c=observationContext(observation,person(),dataForPerson()?.weather);if(!c.active){toast(tr('请检查气温、湿度和风速。','Please check the air temperature, humidity and wind.'));return;}state.measurements[bodyId()]=observation;persist();render();toast(tr('记好啦，穿搭和提醒已一起更新。','Recorded. Your outfit advice and reminders are updated.'));};
$('measurementClear').onclick=()=>{delete state.measurements[bodyId()];persist();$('measurementForm').reset();render();};
$('outfitApply').onclick=()=>{const r=recommendOutfit(dataForPerson()?.adviceWeather,state.feedback[bodyId()],person()?.activity,state.healthProfiles[bodyId()]);if(!r.available)return;state.outfit=r.wear;persist();render();toast(tr('记下这套穿搭建议啦。','Your outfit plan is saved.'));};
$('outfitReset').onclick=()=>{state.outfit='reference';persist();render();};
$('moodClear').onclick=()=>{delete state.moods[bodyId()];persist();render();};
$('jumpDestination').onclick=()=>jump($('destination').value);
$('clearFeedback').onclick=()=>{if(!person())return;delete state.feedback[person().id];persist();state.lastStream=0;syncStream();void poll();render();};
$('bodyForm').onsubmit=e=>{e.preventDefault();const p={heightCm:Number($('heightCm').value),weightKg:Number($('weightKg').value),age:Number($('bodyAge').value),sex:$('bodySex').value};if(['invalid','incomplete'].includes(estimateMetabolism(p).status)){toast(tr('请检查身高、体重和年龄。','Please check height, weight and age.'));return;}state.bodyProfiles[bodyId()]=p;persist();renderMetabolism();toast(tr('记好啦，消耗估算已经更新。','Saved. Your energy estimate is ready.'));};
$('healthForm').onsubmit=e=>{e.preventDefault();if(document.querySelector('[data-health="other"]').checked&&!$('healthOther').value.trim()){toast(tr('写下需要留意的情况吧。','Add the detail you would like us to remember.'));return;}state.healthProfiles[bodyId()]=normalizeHealth({conditions:[...document.querySelectorAll('[data-health]:checked')].map(e=>e.dataset.health),fluidRestricted:$('fluidRestricted').checked,otherText:$('healthOther').value});persist();render();toast(tr('记好啦，提醒也会跟着调整。','Saved. Your reminders will adjust too.'));};
$('clearHealth').onclick=()=>{delete state.advice[bodyId()];delete state.healthProfiles[bodyId()];persist();fillHealthForm();render();};
$('clearRoad').onclick=()=>{state.world?.clearRoad?.();temperatureMap.clearSelection();};
$('clearBody').onclick=()=>{delete state.bodyProfiles[bodyId()];persist();fillBodyForm();renderMetabolism();};
$('mapToolsToggle').onclick=()=>{const open=worldPanel.classList.toggle('controls-open');$('mapToolsToggle').setAttribute('aria-expanded',String(open));};
$('temperatureZoomIn').onclick=()=>temperatureMap.zoom(1.4);$('temperatureZoomOut').onclick=()=>temperatureMap.zoom(1/1.4);$('temperatureReset').onclick=()=>temperatureMap.reset();
$('checkApi').onclick=()=>void checkApi();
$('activity').addEventListener('change',e=>{state.world?.setActivity(e.target.value);state.positions=state.world?.state()||[];render();void poll();syncStream();});
$('waterButton').onclick=()=>{if(!person())return;state.water[person().id]=Date.now();state.lastReminder=Date.now();persist();render();toast(healthSupport(state.healthProfiles[bodyId()]).fluidRestricted?tr('记好啦，按自己的饮水安排来。','Logged. Follow your drinking plan.'):tr('喝水打卡成功，继续慢慢逛吧。','Water break logged. Enjoy your walk.'));};
$('restButton').onclick=()=>{state.world?.setActivity('rest');state.positions=state.world?.state()||[];render();void poll();toast(tr('歇一会儿，看看湖边的风景吧。','Take a breather and enjoy the view.'));};
$('walkRoute').onclick=()=>{if(state.routeRunning){state.world?.stop();state.routeRunning=false;$('walkRoute').textContent=TEXT.walkRoute[state.lang==='zh'?0:1];return;}if(state.reduced){toast(tr('点点方向按钮，慢慢往前走吧。','Use the arrow buttons to take a step at a time.'));return;}state.world?.setActivity('walk');state.world?.routeTo($('destination').value);state.positions=state.world?.state()||[];};
$('language').onchange=e=>{state.lang=e.target.value;persist();applyLanguage();};
$('vision').value=state.vision;$('vision').onchange=e=>{state.vision=e.target.value;document.body.dataset.vision=state.vision;state.world?.setVision(state.vision);renderTemperatureMap();persist();};
$('reduced').checked=state.reduced;$('reduced').onchange=e=>{state.reduced=e.target.checked;document.body.classList.toggle('reduced',state.reduced);state.world?.setReduced(state.reduced);if(state.reduced){state.routeRunning=false;$('walkRoute').textContent=TEXT.walkRoute[state.lang==='zh'?0:1];}persist();};
$('reminderToggle').checked=state.timer;$('reminderToggle').onchange=e=>{state.timer=e.target.checked;state.lastReminder=Date.now();persist();};
$('settingsButton').onclick=()=>{state.world?.stop();$('settings').showModal();};$('sourceButton').onclick=()=>{renderSources();$('sources').showModal();};$('learnButton').onclick=()=>{renderSources(true);$('sources').showModal();};
document.body.dataset.vision=state.vision;document.body.classList.toggle('reduced',state.reduced);applyLanguage();fillBodyForm();fillHealthForm();
setInterval(()=>{$('clock').textContent=hh(Date.now());const d=dataForPerson(),plan=reminderPlan(state.healthProfiles[bodyId()],d?.warningWeather,state.feedback[bodyId()],person()?.activity);if(state.timer&&Date.now()-state.lastReminder>=plan.minutes*60000){state.lastReminder=Date.now();toast(plan[state.lang]);}},1000);
setInterval(()=>{if(!state.sse)void poll();else syncStream();},5000);
window.addEventListener('pagehide',()=>state.stream?.close());

function personalOffset(id){const c=state.calib[id];if(!c)return null;const n=(c.hot||0)+(c.cold||0)+(c.fine||0);if(n<3)return null;return Math.max(-2,Math.min(2,2*((c.hot||0)-(c.cold||0))/n));}
let ragPromise=null;
function loadRag(){if(ragPromise)return ragPromise;ragPromise=new Promise((resolve,reject)=>{const kb=document.createElement('script');kb.src='/rag/kb_v1.js';kb.onload=()=>{const rt=document.createElement('script');rt.src='/rag/retrieve.js';rt.onload=()=>{try{resolve(window.FeelsLikeRAG.load(window.FEELSLIKE_KB));}catch(e){reject(e);}};rt.onerror=reject;document.head.append(rt);};kb.onerror=reject;document.head.append(kb);});return ragPromise;}
async function evidenceFor(question){const rag=await loadRag();const month=new Date().getMonth()+1;const season=month>=3&&month<=5?'spring':month>=6&&month<=8?'summer':month>=9&&month<=11?'autumn':'winter';return rag.retrieve({question,place:'西湖',activity:person()?.activity,chain:'decision',season},{topK:4});}
function renderChat(id){const box=$('aiAdviceResult');box.replaceChildren();const chat=(state.aiChat[id]||[]).slice(-20);if(!chat.length){box.textContent=tr('还没有对话。点上面按钮开始。','No conversation yet. Use the button above to start.');return;}for(const m of chat){const row=document.createElement('div');row.className='ai-msg '+(m.role==='user'?'ai-user':'ai-assistant');const who=document.createElement('b');who.textContent=m.role==='user'?tr('你','You'):'FeelsLike';const body=document.createElement('span');body.textContent=m.content;row.append(who,body);box.append(row);}box.scrollTop=box.scrollHeight;}
function renderEvidence(pack){const box=$('aiEvidence');if(!box)return;box.replaceChildren();if(!pack){box.hidden=true;return;}box.hidden=false;const head=document.createElement('b');head.textContent=pack.coverage?tr('证据依据（可溯源）','Evidence (traceable)'):tr('证据不足，仅列出处','Insufficient evidence; sources only');box.append(head);for(const c of (pack.cards||[])){const li=document.createElement('div');li.className='ai-ev-card';const t=document.createElement('span');t.textContent='['+c.id+'] '+c.title+(c.numbers_allowed?'':'（题录级，不给数字）');li.append(t);if(c.url){const a=document.createElement('a');a.href=c.url;a.target='_blank';a.rel='noopener';a.textContent='DOI/来源';li.append(a);}box.append(li);}const note=document.createElement('small');note.textContent=tr('检索为确定性硬门控；AI 建议只可引用上述出处，不编造数字。','Deterministic hard-gated retrieval; AI may only cite the above, never invent numbers.');box.append(note);}
$('aiClearChat').onclick=()=>{const id=bodyId();state.aiChat[id]=[];persist();renderChat(id);renderEvidence(null);};
renderChat(bodyId());
$('aiAdviceButton').onclick=async()=>{
 const button=$('aiAdviceButton'),id=bodyId();button.disabled=true;
 const question=$('aiQuestion').value.trim(),userText=question||tr('给我这次出行的建议。','Give me advice for this outing.');
 const chat=state.aiChat[id]||(state.aiChat[id]=[]);chat.push({role:'user',content:userText,at:Date.now()});if(chat.length>40)chat.splice(0,chat.length-40);
 $('aiQuestion').value='';renderChat(id);
 const d=dataForPerson(),requestLang=state.lang;delete state.advice[id];renderOverhead(d);
 let evidence='',evidenceIds=null,pack=null;try{pack=await evidenceFor(userText);}catch{pack=null;}
 if(pack){evidence=window.FeelsLikeRAG.formatEvidencePack(pack);evidenceIds=(pack.cards||[]).map(c=>c.id);}renderEvidence(pack);
 const snapshot=buildAdviceSnapshot(state,d,{doctorAdvice:$('aiDoctor').value,question:userText,destination:placeFor(person()),history:chat.slice(0,-1).map(m=>({role:m.role,content:m.content})),evidence,evidenceIds,offsetC:personalOffset(id)});
 const thinking=document.createElement('div');thinking.className='ai-msg ai-assistant';thinking.textContent=tr('正在结合天气、你的情况和证据想一想…','Thinking with weather, your profile and evidence…');$('aiAdviceResult').append(thinking);
 try{const r=await fetch('/api/health-advice',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(snapshot),signal:AbortSignal.timeout(95000)}),data=await r.json();if(!r.ok){const e=Error();e.code=data.code;throw e;}chat.push({role:'assistant',content:data.text,at:Date.now()});state.advice[id]={text:data.text,summary:data.summary||compactAdvice(data.text,requestLang),generatedAt:data.generatedAt,lang:requestLang,provider:'DeepSeek'};$('aiAdviceTime').textContent='DeepSeek · '+hh(data.generatedAt)+tr(' · 多轮对话',' · multi-turn');}
 catch(e){const support=healthSupport(state.healthProfiles[id],d?.warningWeather),text=(e.code==='not_configured'?tr('AI连接还没配置好。','The AI connection is not configured yet.'):e.code==='rate_limited'?tr('稍等一会儿再问吧。','Please wait a moment before asking again.'):tr('AI这会儿没连上，先看看这条提醒。','AI could not connect. Here is your current reminder.'))+'\n\n'+(support[state.lang]||$('actionBody').textContent);chat.push({role:'assistant',content:text,at:Date.now()});state.advice[id]={text,summary:compactAdvice(text,state.lang),generatedAt:Date.now(),lang:state.lang,provider:'basic'};$('aiAdviceTime').textContent=tr('基础提醒','Basic reminder');}
 finally{button.disabled=false;persist();renderChat(id);renderOverhead(dataForPerson());}
};


function renderPointThermal(d){if(!state.shadowPreview){const t=new Date(Date.now()+8*3600000),minutes=t.getUTCHours()*60+t.getUTCMinutes();$('sunHour').value=minutes;$('sunHourLabel').textContent=String(t.getUTCHours()).padStart(2,'0')+':'+String(t.getUTCMinutes()).padStart(2,'0');}const local=d?.geometryThermal,shade=d?.shadeContext;$('pointThermalValue').textContent=local?local.value.toFixed(1)+' °C':'-- °C';$('pointShadeState').textContent=shade?(shade.sun.daylight?tr('当前位置遮蔽约 '+Math.round(shade.shade*100)+'% · 太阳高度 '+shade.sun.elevation.toFixed(0)+'°','Local shade '+Math.round(shade.shade*100)+'% · Sun altitude '+shade.sun.elevation.toFixed(0)+'°'):tr('太阳已落山，没有直射日光。','The sun is below the horizon.')):tr('正在读取场景遮蔽…','Reading scene shade…');$('pointThermalSource').textContent=local?(state.shadowPreview?tr('日照演示 · 当前温湿风 · ','Sun preview · current air/humidity/wind · '):'')+(local.daylight?tr('日晒参考 '+local.sunValue.toFixed(1)+'°C → 当前 '+local.value.toFixed(1)+'°C · 阴影影响 '+local.shadeDelta.toFixed(1)+'°C','Sun reference '+local.sunValue.toFixed(1)+'°C → here '+local.value.toFixed(1)+'°C · shade effect '+local.shadeDelta.toFixed(1)+'°C'):tr('夜间没有直射日光，树影不改变这项体感。','No direct sunlight at night; shade adds no solar cooling.'))+'\n'+tr('辐射：','Radiation: ')+(local.radiationEstimated?tr('晴空模型估算','clear-sky model estimate'):tr('气象预报','weather forecast'))+' · '+Math.round(local.inputRadiation)+' W/m²':tr('等待有效的气温、湿度和风速。','Waiting for air temperature, humidity and wind.');$('weatherProviderNote').textContent=state.weatherProvider==='tjweather'?tr('11/16 下载快照 · 81个请求点；辐射可参考已取得的 Open-Meteo，体感为估算。','Nov 16 snapshot · 81 requested points; available Open-Meteo radiation supplements the estimate.'):tr('在线区域预报，原始气象值保留。','Online regional forecast; source readings are preserved.');}
$('temperatureDismiss').onclick=()=>{state.mapCoordinate=null;temperatureMap.clearSelection();renderTemperatureMap();};
$('weatherProvider').onchange=e=>{if(state.pending){e.target.value=state.weatherProvider;toast(tr('天气更新完再切换吧。','Please wait for the weather update.'));return;}state.weatherProvider=e.target.value;persist();state.telemetry=null;void poll();};
$('shadowTime').onchange=e=>{const time=Date.parse(e.target.value+'+08:00');if(Number.isFinite(time)){const clock=e.target.value.slice(11,16);$('sunHourLabel').textContent=clock;$('sunHour').value=Number(clock.slice(0,2))*60+Number(clock.slice(3));}state.shadowPreview=Number.isFinite(time)?time:null;$('sunMode').value=state.shadowPreview?'manual':'live';state.world?.setShadowTime?.(state.shadowPreview);render();};
function setManualSun(){const minutes=Number($('sunHour').value),h=String(Math.floor(minutes/60)).padStart(2,'0'),m=String(minutes%60).padStart(2,'0'),date=$('shadowTime').value.slice(0,10)||new Date(Date.now()+8*3600000).toISOString().slice(0,10);$('sunHourLabel').textContent=h+':'+m;$('shadowTime').value=date+'T'+h+':'+m;$('sunMode').value='manual';state.shadowPreview=Date.parse(date+'T'+h+':'+m+':00+08:00');state.world?.setShadowTime?.(state.shadowPreview);render();}
$('sunHour').oninput=setManualSun;$('sunMode').onchange=()=>{if($('sunMode').value==='manual')setManualSun();else $('shadowNow').click();};
$('shadowNow').onclick=()=>{state.shadowPreview=null;$('sunMode').value='live';$('shadowTime').value='';state.world?.setShadowTime?.(null);render();};

$('weatherProvider').value=state.weatherProvider;
void weatherClient.load().then(cache=>{regionalCache=cache;if(state.weatherProvider==='tjweather')void poll();}).catch(()=>{});
void poll();
try{state.world=await createWorld($('scene'),{avatarId:state.avatarId,outfit:state.outfit,reduced:state.reduced,vision:state.vision,onProgress:({stage,pct})=>{const s=$('loadStage'),b=$('loadBar');if(s)s.textContent=stage;if(b)b.style.width=pct+'%';},onMove:p=>{state.positions=p;render();syncStream();},onRoad:road=>{state.road=road;renderRoad();},onRoute:r=>{state.routeReport=r;state.routeRunning=!!r.ok&&!r.paused;renderRouteStatus();},onError:code=>toast(code==='avatar'?tr('人物还没加载好，稍后可以再选一次。','The character is still loading. Try choosing it again.'):code==='WebGL'?tr('点击地图，就能开始漫步。','Tap the map to take a walk.'):tr('试试点击地图，换个地方逛逛。','Try tapping the map to explore somewhere else.'))});state.positions=state.world.state();state.world.setLang(state.lang);state.world.setShadowTime?.(state.shadowPreview);temperatureMap.setData(state.world.data);render();void poll();try{const h=await fetch('/api/health').then(r=>r.json());state.sse=false;}catch{}}
catch(e){$('loading').textContent=tr('地图未能载入，请刷新重试。','The map could not load. Please refresh to retry.');toast(tr('地图资源连接失败。','Could not load map assets.'));}
